'use client';

import React, { useState } from 'react';
import { Calculator, Home, Building, ArrowRight } from 'lucide-react';

const PropertyValueCalculator = () => {
    const [lookingTo, setLookingTo] = useState('Sell');
    const [propertyType, setPropertyType] = useState('Apartment');
    const [bedrooms, setBedrooms] = useState('1');
    const [area, setArea] = useState('');
    const [project, setProject] = useState('');
    const [locality, setLocality] = useState('Andheri West, Mumbai');
    const [city, setCity] = useState('Mumbai');

    const propertyTypes = ['Apartment', 'Independent Floor', 'Independent House', 'Villa'];
    const bedroomOptions = ['1', '2', '3', '4', '5+'];

    return (
        <div className="min-h-screen bg-[#B88746] relative overflow-hidden flex items-center justify-center p-4">
            {/* Background Decorations (Abstract Houses/Patterns similar to image) */}
            <div className="absolute top-0 right-0 w-full h-full opacity-10 pointer-events-none">
                <div className="absolute top-20 right-20 transform rotate-12">
                    <Home className="w-64 h-64 text-white" />
                </div>
                <div className="absolute bottom-10 left-10 transform -rotate-12">
                    <Calculator className="w-48 h-48 text-white" />
                </div>
            </div>

            <div className="bg-white rounded-[2rem] shadow-2xl w-full max-w-3xl relative z-10 p-8 md:p-12 animate-fadeIn">
                <div className="mb-8">
                    <h1 className="text-3xl font-bold text-gray-900">Property Value Calculator</h1>
                    <p className="text-gray-500 mt-2 text-sm">Let's calculate sale or rent value in seconds</p>
                </div>

                <div className="space-y-8">
                    {/* Looking to: Sell/Rent */}
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 mb-3">Looking to <span className="text-red-500">*</span></label>
                        <div className="flex gap-4">
                            {['Sell', 'Rent'].map((option) => (
                                <button
                                    key={option}
                                    onClick={() => setLookingTo(option)}
                                    className={`px-6 py-2 rounded-lg text-sm font-medium transition-all border
                                        ${lookingTo === option
                                            ? 'bg-purple-100 text-purple-700 border-purple-200'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {option}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* City & Project */}
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">City <span className="text-red-500">*</span></label>
                            <input
                                type="text"
                                value={city}
                                onChange={(e) => setCity(e.target.value)}
                                className="w-full border-b border-gray-200 py-2 focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium"
                                placeholder="Enter City"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">Project</label>
                            <input
                                type="text"
                                value={project}
                                onChange={(e) => setProject(e.target.value)}
                                className="w-full border-b border-gray-200 py-2 focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium"
                                placeholder="Enter Project Name"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-semibold text-gray-700 mb-2">Locality <span className="text-red-500">*</span></label>
                            <input
                                type="text"
                                value={locality}
                                onChange={(e) => setLocality(e.target.value)}
                                className="w-full border-b border-gray-200 py-2 focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium"
                                placeholder="Enter Locality"
                            />
                        </div>
                    </div>

                    {/* Property Type */}
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 mb-3">Property Type <span className="text-red-500">*</span></label>
                        <div className="flex flex-wrap gap-3">
                            {propertyTypes.map((type) => (
                                <button
                                    key={type}
                                    onClick={() => setPropertyType(type)}
                                    className={`px-4 py-2 rounded-lg text-xs font-medium transition-all border
                                        ${propertyType === type
                                            ? 'bg-purple-100 text-purple-700 border-purple-200'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {type}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Bedrooms */}
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 mb-3">Bedrooms <span className="text-red-500">*</span></label>
                        <div className="flex flex-wrap gap-3">
                            {bedroomOptions.map((opt) => (
                                <button
                                    key={opt}
                                    onClick={() => setBedrooms(opt)}
                                    className={`w-10 h-10 flex items-center justify-center rounded-lg text-sm font-medium transition-all border
                                        ${bedrooms === opt
                                            ? 'bg-purple-100 text-purple-700 border-purple-200'
                                            : 'bg-white text-gray-500 border-gray-200 hover:border-gray-300'
                                        }`}
                                >
                                    {opt}
                                </button>
                            ))}
                        </div>
                    </div>

                    {/* Area */}
                    <div>
                        <label className="block text-sm font-semibold text-gray-700 mb-2">Area (sq.ft) <span className="text-red-500">*</span></label>
                        <input
                            type="number"
                            value={area}
                            onChange={(e) => setArea(e.target.value)}
                            className="w-full border-b border-gray-200 py-2 focus:outline-none focus:border-purple-500 text-gray-900 placeholder-gray-400 font-medium"
                            placeholder="0"
                        />
                    </div>

                    <div className="pt-4">
                        <button className="w-full bg-[#172747] text-white py-4 rounded-xl font-bold text-lg hover:bg-[#0f1b33] transition-colors flex items-center justify-center gap-2">
                            Calculate Value
                            <ArrowRight className="w-5 h-5" />
                        </button>
                    </div>

                </div>
            </div>

            <style jsx global>{`
                @keyframes fadeIn {
                    from { opacity: 0; transform: translateY(20px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-fadeIn {
                    animation: fadeIn 0.4s ease-out forwards;
                }
            `}</style>
        </div>
    );
};

export default PropertyValueCalculator;
